import type { RuntimeBindings } from "../bindings";
import * as React from "react";
import * as ReactDOM from "react-dom";
import * as jsxRuntime from "react/jsx-runtime";
import * as ReactDOMClient from "react-dom/client";
import { Menu as NpmMenu } from "@base-ui/react/menu";
import { ContextMenu as NpmContextMenu } from "@base-ui/react/context-menu";
import { Popover as NpmPopover } from "@base-ui/react/popover";
import { Combobox as NpmCombobox } from "@base-ui/react/combobox";
import { Tooltip as NpmTooltip } from "@base-ui/react/tooltip";
import { Collapsible as NpmCollapsible } from "@base-ui/react/collapsible";
import { Field as NpmField } from "@base-ui/react/field";
import { Dialog as NpmDialog } from "@base-ui/react/dialog";
import { AlertDialog as NpmAlertDialog } from "@base-ui/react/alert-dialog";
import { Radio as NpmRadio } from "@base-ui/react/radio";
import { Tabs as NpmTabs } from "@base-ui/react/tabs";
import { Toast as NpmToast } from "@base-ui/react/toast";
import { RadioGroup as NpmRadioGroup } from "@base-ui/react/radio-group";
import { Button as NpmButton } from "@base-ui/react/button";
import { useRender as NpmUseRender } from "@base-ui/react/use-render";
import { mergeProps as NpmMergeProps } from "@base-ui/react/merge-props";
import { LabelableProvider as NpmLabelableProvider } from "@base-ui/react/internals/labelable-provider";
import { Checkbox as NpmCheckbox } from "@base-ui/react/checkbox";
import { Switch as NpmSwitch } from "@base-ui/react/switch";
import { NumberField as NpmNumberField } from "@base-ui/react/number-field";
import { Fieldset as NpmFieldset } from "@base-ui/react/fieldset";
import { Menubar as NpmMenubar } from "@base-ui/react/menubar";
import { useLabelableContext as NpmUseLabelableContext } from "@base-ui/react/internals/labelable-provider";
import { cva as NpmCva } from "class-variance-authority";
import { clsx as NpmClsx } from "clsx";
import { extendTailwindMerge as NpmExtendTailwindMerge } from "tailwind-merge";
import { validators as NpmValidators } from "tailwind-merge";
import PptxPresentation from "pptxgenjs";

declare module "../bindings" {
  interface RuntimeBindings {
    loadReactNamespace: () => typeof React;
    loadReactDomNamespace: () => typeof ReactDOM;
    loadJsxNamespace: () => typeof jsxRuntime;
    loadReactDomClientNamespace: () => typeof ReactDOMClient;
    baseMenu: typeof NpmMenu;
    baseContextMenu: typeof NpmContextMenu;
    basePopover: typeof NpmPopover;
    baseCombobox: typeof NpmCombobox;
    baseTooltip: typeof NpmTooltip;
    baseCollapsible: typeof NpmCollapsible;
    baseField: typeof NpmField;
    baseDialog: typeof NpmDialog;
    baseAlertDialog: typeof NpmAlertDialog;
    baseRadio: typeof NpmRadio;
    baseTabs: typeof NpmTabs;
    baseToast: typeof NpmToast;
    baseRadioGroup: typeof NpmRadioGroup;
    baseButton: typeof NpmButton;
    baseUseRender: typeof NpmUseRender;
    baseMergeProps: typeof NpmMergeProps;
    baseLabelableProvider: typeof NpmLabelableProvider;
    baseCheckbox: typeof NpmCheckbox;
    baseSwitch: typeof NpmSwitch;
    baseNumberField: typeof NpmNumberField;
    baseFieldsetRoot: typeof NpmFieldset.Root;
    baseMenubar: typeof NpmMenubar;
    baseUseLabelableContext: typeof NpmUseLabelableContext;
    cva: typeof NpmCva;
    clsx: typeof NpmClsx;
    extendTailwindMerge: typeof NpmExtendTailwindMerge;
    validators: typeof NpmValidators;
    PptxPresentation: typeof PptxPresentation;
    PPTX_EMU: number;
    initializeNpmDependency: () => void;
  }
}

/** npm surfaces replacing bundled third-party code; application wrappers stay in their source modules. */
export function installLibraries(runtime: RuntimeBindings): void {
  runtime.loadReactNamespace = () => React;
  runtime.loadReactDomNamespace = () => ReactDOM;
  runtime.loadJsxNamespace = () => jsxRuntime;
  runtime.loadReactDomClientNamespace = () => ReactDOMClient;
  runtime.baseMenu = NpmMenu;
  runtime.baseContextMenu = NpmContextMenu;
  runtime.basePopover = NpmPopover;
  runtime.baseCombobox = NpmCombobox;
  runtime.baseTooltip = NpmTooltip;
  runtime.baseCollapsible = NpmCollapsible;
  runtime.baseField = NpmField;
  runtime.baseDialog = NpmDialog;
  runtime.baseAlertDialog = NpmAlertDialog;
  runtime.baseRadio = NpmRadio;
  runtime.baseTabs = NpmTabs;
  runtime.baseToast = NpmToast;
  runtime.baseRadioGroup = NpmRadioGroup;
  runtime.baseButton = NpmButton;
  runtime.baseUseRender = NpmUseRender;
  runtime.baseMergeProps = NpmMergeProps;
  runtime.baseLabelableProvider = NpmLabelableProvider;
  runtime.baseCheckbox = NpmCheckbox;
  runtime.baseSwitch = NpmSwitch;
  runtime.baseNumberField = NpmNumberField;
  runtime.baseFieldsetRoot = NpmFieldset.Root;
  runtime.baseMenubar = NpmMenubar;
  runtime.baseUseLabelableContext = NpmUseLabelableContext;
  runtime.cva = NpmCva;
  runtime.clsx = NpmClsx;
  runtime.extendTailwindMerge = NpmExtendTailwindMerge;
  runtime.validators = NpmValidators;
  runtime.PptxPresentation = PptxPresentation;
  runtime.PPTX_EMU = 914400;
  runtime.initializeNpmDependency = () => {};
}
